        <div className="cv-blueprint-titleblock">
          <span>{name}</span>
          <span>{role}</span>
          <span aria-hidden="true">A4 / 01</span>
        </div>
      </>
    );

  if (data.layout === "orbit")
    return (
      <>
        <header className="cv-orbit-header">
          <div>
            <span className="cv-digital-label" aria-hidden="true">
              CURIOSITY IN PRACTICE
